export const editorToolApiVersion=1;
export const editorToolMethods=['scene.place','scene.select','document.patch','viewport.configure','viewport.action','viewport.bookmark','window.open','window.close','window.detach','window.redock','editor.eqs.run','editor.eqs.read','editor.eqs.view'];
export const editorToolContract={assetVersion:1,editorOnly:true,apiVersion:editorToolApiVersion,methods:editorToolMethods,manifest:'Optional api:{version:1,requires:[method names]}; legacy files retain implicit capabilities. Explicit manifests must declare every action method. Unsupported versions/capabilities fail before dispatch.',templates:['$input','$context:scene|active|selection','$revision:scene|active'],execution:'One validated command per action; cloned inputs/templates/context and one revision read per path, current-owner/cancel guard before dispatch. Actual dispatched command result/error is preserved; no implicit retry or rollback.',output:'Optional action output:json; bounded text preview only. No eval, arbitrary JavaScript or method name templating.',lifetime:'One in-flight action per editor, all inputs/actions/configuration disabled during it. Closing/replacing editor cancels preflight; a dispatched API command retains its own revision/Undo semantics.',remaining:['native/code extension ABI and distribution','multi-command transactional workflows','arbitrary dispatched command cancellation/rollback']};
const id=v=>typeof v==='string'&&/^[A-Za-z][A-Za-z0-9_]{0,63}$/.test(v),text=v=>typeof v==='string'&&v.length>0&&v.length<=200;
export function validToolInput(f,value){return f.type==='number'?Number.isFinite(value)&&value>=(f.min??-1e6)&&value<=(f.max??1e6):f.type==='bool'?typeof value==='boolean':f.type==='vec3'?Array.isArray(value)&&value.length===3&&value.every(v=>Number.isFinite(v)&&Math.abs(v)<=1e6):f.type==='select'?f.choices?.some(c=>c.value===value):typeof value==='string'&&value.length<=2000;}
function validTemplate(value,inputs,depth=0){if(depth>12)return false;if(value===null||typeof value==='boolean'||typeof value==='string')return typeof value!=='string'||value.length<=4000;if(typeof value==='number')return Number.isFinite(value);if(Array.isArray(value))return value.length<=1000&&value.every(v=>validTemplate(v,inputs,depth+1));if(!value||typeof value!=='object')return false;const keys=Object.keys(value);if(keys.some(k=>['__proto__','prototype','constructor'].includes(k)))return false;if(keys.some(k=>k.startsWith('$')))return keys.length===1&&(keys[0]==='$input'&&inputs.has(value.$input)||keys[0]==='$context'&&['scene','active','selection'].includes(value.$context)||keys[0]==='$revision'&&['scene','active'].includes(value.$revision));return keys.length<=1000&&keys.every(k=>validTemplate(value[k],inputs,depth+1));}
export function validEditorTool(data){
 if(!data||data.version!==1||!text(data.name)||!Array.isArray(data.inputs)||data.inputs.length>128||!Array.isArray(data.actions)||data.actions.length>128)return false;
 if(data.api!==undefined&&(!data.api||typeof data.api!=='object'||Array.isArray(data.api)||Object.keys(data.api).some(k=>!['version','requires'].includes(k))||data.api.version!==editorToolApiVersion||!Array.isArray(data.api.requires)||data.api.requires.length>editorToolMethods.length||new Set(data.api.requires).size!==data.api.requires.length||data.api.requires.some(method=>!editorToolMethods.includes(method))))return false;
 const inputs=new Set();for(const f of data.inputs){if(!f||!id(f.id)||inputs.has(f.id)||!text(f.label)||!['number','text','bool','vec3','select'].includes(f.type)||f.type==='select'&&(!Array.isArray(f.choices)||!f.choices.length||f.choices.length>128||f.choices.some(c=>!text(c.label)||!text(c.value))||new Set(f.choices.map(c=>c.value)).size!==f.choices.length)||f.min!==undefined&&!Number.isFinite(f.min)||f.max!==undefined&&!Number.isFinite(f.max)||!validToolInput(f,f.default))return false;inputs.add(f.id);}
 const actions=new Set();return data.actions.every(a=>a&&id(a.id)&&!actions.has(a.id)&&actions.add(a.id)&&text(a.label)&&editorToolMethods.includes(a.method)&&(!data.api||data.api.requires.includes(a.method))&&(a.output===undefined||['none','json'].includes(a.output))&&a.params&&typeof a.params==='object'&&!Array.isArray(a.params)&&validTemplate(a.params,inputs));
}
export function inspectEditorTool(data,methods={}){if(!validEditorTool(data))throw Error('편집기 도구 정의·API 버전을 확인하세요.');const requires=data.api?.requires||[...new Set(data.actions.map(a=>a.method))],missing=requires.filter(method=>!Object.hasOwn(methods,method)||typeof methods[method]!=='function');return {assetVersion:data.version,apiVersion:editorToolApiVersion,explicitAPI:!!data.api,compatible:!missing.length,requires:[...requires],missing,inputs:structuredClone(data.inputs),actions:data.actions.map(a=>({id:a.id,label:a.label,method:a.method,output:a.output??'none'}))};}
export const editorToolCancelled=()=>Object.assign(Error('편집기 도구의 실행 준비가 취소됐어요.'),{code:'EDITOR_TOOL_CANCELLED',dispatched:false});
export function editorToolOutput(value){let nodes=0;const seen=new WeakSet(),visit=(value,depth=0)=>{if(++nodes>512||depth>6)return '…';if(typeof value==='string')return value.length>500?value.slice(0,500)+'…':value;if(typeof value==='bigint')return String(value);if(!value||typeof value!=='object')return value;if(seen.has(value))return '[반복 참조]';seen.add(value);if(Array.isArray(value)){const out=[];for(let i=0;i<Math.min(value.length,64)&&nodes<512;i++)out.push(visit(value[i],depth+1));if(out.length<value.length)out.push('…');return out;}const out=Object.create(null);let count=0;for(const key in value)if(Object.hasOwn(value,key)){if(count++>=64||nodes>=512){out['…']='…';break;}out[key]=visit(value[key],depth+1);}return out;};return (JSON.stringify(visit(value),null,2)??'완료').slice(0,4000);}

export function createEditorTool(name){return {version:1,name,inputs:[{id:'position',label:'위치',type:'vec3',default:[0,0,0]},{id:'kind',label:'오브젝트',type:'select',default:'cube',choices:[{label:'큐브',value:'cube'},{label:'스프라이트',value:'sprite'},{label:'점 광원',value:'pointLight'},{label:'스카이라이트',value:'skyLight'}]}],actions:[{id:'place',label:'배치',method:'scene.place',params:{path:{$context:'scene'},expectedRevision:{$revision:'scene'},key:{$input:'kind'},position:{$input:'position'}}}]};}
export async function runEditorTool(data,actionId,values,context,methods,{current=()=>true,signal}={}){
 const guard=()=>{if(signal?.aborted||!current()||context.current&&!context.current())throw editorToolCancelled();};guard();
 const compatibility=inspectEditorTool(data,methods);if(data.api&&!compatibility.compatible)throw Error('도구에 필요한 명령이 없어요: '+compatibility.missing.join(', '));const found=data.actions.find(a=>a.id===actionId);if(!found||!Object.hasOwn(methods,found.method)||typeof methods[found.method]!=='function')throw Error('도구 명령을 확인하세요.');const action=structuredClone(found),method=methods[action.method];
 if(!values||typeof values!=='object'||Array.isArray(values)||Object.keys(values).some(k=>!data.inputs.some(f=>f.id===k)))throw Error('도구 입력을 확인하세요.');const inputs={};for(const f of data.inputs){const v=Object.hasOwn(values,f.id)?values[f.id]:f.default;if(!validToolInput(f,v))throw Error('도구 입력을 확인하세요: '+f.label);inputs[f.id]=structuredClone(v);}
 const captured={scene:structuredClone(context.scene),active:structuredClone(context.active),selection:structuredClone(context.selection)},revisions=new Map();
 const resolve=async value=>{guard();if(!value||typeof value!=='object')return value;if(Object.hasOwn(value,'$input'))return structuredClone(inputs[value.$input]);if(Object.hasOwn(value,'$context'))return structuredClone(captured[value.$context]);if(Object.hasOwn(value,'$revision')){const path=captured[value.$revision];if(!revisions.has(path))revisions.set(path,Promise.resolve().then(()=>{guard();return context.revision(path);}));const revision=await revisions.get(path);guard();return revision;}if(Array.isArray(value))return Promise.all(value.map(resolve));const result={};for(const [key,v]of Object.entries(value))result[key]=await resolve(v);return result;};
 const params=await resolve(action.params);guard();if(methods[action.method]!==method)throw Object.assign(Error('도구 명령이 준비 중 바뀌었어요.'),{code:'EDITOR_TOOL_CAPABILITY_CHANGED',dispatched:false});return method.call(methods,params);
}
